const radiusMap = {
  "velvet seed beads": 16,
  "woven micro facets": 22,
  "polished hexagonal scales": 30,
  "gilded cabochons": 40,
  "heavy cut gemstones": 50,
  "monumental crystal tiles": 60,
  "monolithic prism plates": 70
};

const waveMap = {
  "gentle tidal swell": (x, y, t) => Math.sin(y*0.01 + t*1.5)*0.5 + Math.sin(x*0.005 + t)*0.5,
  "diagonal cross current": (x, y, t) => Math.sin((x+y)*0.015 - t*3),
  "rippling radial rings": (x, y, t) => Math.sin(Math.hypot(x, y)*0.02 - t*4),
  "braided Lissajous rollers": (x, y, t) => Math.sin(x*0.01 + Math.cos(t))*Math.cos(y*0.01 + Math.sin(t)),
  "accordion snap pulse": (x, y, t) => Math.sin(x*0.04 - t*4) + Math.cos(y*0.02 + t*2),
  "chaotic stormy boil": (x, y, t) => Math.sin(x*0.04 + t*3)*Math.cos(y*0.03 - t*2.5) + Math.sin((x-y)*0.02 + t*4)
};

const orbitMap = {
  "lazy equatorial drift": (t) => [Math.cos(t)*1000, 300, Math.sin(t)*1000 + 400],
  "gentle sub-tropic sway": (t) => [Math.cos(t*0.8)*800, 500, Math.sin(t*0.8)*800 + 400],
  "steep polar transit": (t) => [0, Math.cos(t*1.5)*1000, Math.sin(t*1.5)*1000 + 100],
  "close skimming pass": (t) => [Math.cos(t*2.5)*400, Math.sin(t*2.5)*400, 150],
  "rapid spiral descent": (t) => [Math.cos(t*4)*(500 - (t%200)*2), Math.sin(t*4)*(500 - (t%200)*2), Math.max(100, 800 - (t%200)*3)],
  "distant zenith point": (t) => [100 + Math.cos(t*0.5)*500, -200 + Math.sin(t*0.5)*500, 800]
};

const sheenMap = {
  "satin bisque ceramic": { amb: 0.3, diff: 0.7, spec: 0.15, exp: 4, col: [230, 220, 210] },
  "brushed burnished brass": { amb: 0.25, diff: 0.6, spec: 0.8, exp: 12, col: [220, 180, 70] },
  "holographic oil slick": { amb: 0.25, diff: 0.5, spec: 0.9, exp: 32, col: [150, 150, 150] }, 
  "high chrome mirrors": { amb: 0.2, diff: 0.2, spec: 1.5, exp: 64, col: [245, 250, 255] },
  "iridescent mother of pearl": { amb: 0.3, diff: 0.5, spec: 0.6, exp: 16, col: [240, 230, 235] },
  "matte volcanic glass": { amb: 0.35, diff: 0.4, spec: 0.9, exp: 48, col: [110, 95, 115] }
};

const tiltMap = {
  "subtle shimmering breath": 0.3,
  "gentle trembling sigh": 0.5,
  "crisp cascading dominoes": 0.8,
  "steep rolling crests": 1.4,
  "wild fluttering flip": 2.2,
  "violent jagged scatter": 3.5
};

const SQRT3 = Math.sqrt(3);

let currentGrid = null;
let hexX = new Float32Array(2000);
let hexY = new Float32Array(2000);
let hexCount = 0;

const buckets = [];
for (let i = 0; i < 16; i++) {
  buckets.push({ r: 0, g: 0, b: 0, count: 0, x: new Float32Array(2000), y: new Float32Array(2000) });
}

p.setup = function() {
  p.createCanvas(800, 800);
  p.noStroke();
};

p.draw = function() {
  const vGrid = p.getSynthVar('grid_density') || "velvet seed beads";
  const vWave = p.getSynthVar('wave_dynamics') || "gentle tidal swell";
  const vOrbit = p.getSynthVar('light_orbit') || "lazy equatorial drift";
  const vSheen = p.getSynthVar('specular_sheen') || "satin bisque ceramic";
  const vTilt = p.getSynthVar('tilt_amplitude') || "subtle shimmering breath";

  const radius = radiusMap[vGrid] || radiusMap["velvet seed beads"];

  if (currentGrid !== vGrid) {
    hexCount = 0;
    const w = SQRT3 * radius;
    const h = 2 * radius;
    const xStep = w;
    const yStep = h * 0.75;

    const cols = Math.ceil(1000 / xStep) + 2;
    const rows = Math.ceil(1000 / yStep) + 2;

    for (let row = -2; row < rows; row++) {
      for (let col = -2; col < cols; col++) {
        let cx = col * xStep;
        let cy = row * yStep;
        if (row % 2 !== 0) cx += w * 0.5;
        if (hexCount < 2000) {
          hexX[hexCount] = cx - 100;
          hexY[hexCount] = cy - 100;
          hexCount++;
        }
      }
    }
    currentGrid = vGrid;
  }

  const waveFn = waveMap[vWave] || waveMap["gentle tidal swell"];
  const orbitFn = orbitMap[vOrbit] || orbitMap["lazy equatorial drift"];
  const mat = sheenMap[vSheen] || sheenMap["satin bisque ceramic"];
  const maxTilt = tiltMap[vTilt] || tiltMap["subtle shimmering breath"];

  const t = p.frameCount * 0.016;
  const L = orbitFn(t);

  const lx = L[0], ly = L[1], lz = L[2];
  const ll = Math.sqrt(lx*lx + ly*ly + lz*lz) || 1.1;
  const nlx = lx/ll, nly = ly/ll, nlz = lz/ll;

  const viewZ = 1.0;
  const hx = nlx, hy = nly, hz = nlz + viewZ;
  const hl = Math.sqrt(hx*hx + hy*hy + hz*hz) || 1.1;
  const nhx = hx/hl, nhy = hy/hl, nhz = hz/hl;

  const isHolo = vSheen === "holographic oil slick";
  const isPearl = vSheen === "iridescent mother of pearl";

  for (let i = 0; i < 16; i++) {
    buckets[i].r = 0; buckets[i].g = 0; buckets[i].b = 0;
    buckets[i].count = 0;
  }

  for (let i = 0; i < hexCount; i++) {
    const hxPos = hexX[i];
    const hyPos = hexY[i];

    const basePhase = waveFn(hxPos, hyPos, t);

    const dx = Math.sin(basePhase * 2.5) * maxTilt;
    const dy = Math.sin(basePhase * 1.7) * maxTilt;

    let nx = -dx, ny = -dy, nz = 1.0;
    let nl = Math.sqrt(nx*nx + ny*ny + nz*nz);
    nx /= nl; ny /= nl; nz /= nl;

    const dotL = Math.abs(nx*nlx + ny*nly + nz*nlz); 
    const dotH = Math.abs(nx*nhx + ny*nhy + nz*nhz); 

    const specular = Math.pow(Math.max(0, dotH), mat.exp) * mat.spec;

    let r = mat.col[0], g = mat.col[1], b = mat.col[2];

    if (isHolo) {
       const hueOff = (nx * 150 + ny * 150 + t * 40) % 360;
       r = 150 + Math.sin(hueOff*0.017)*105;
       g = 150 + Math.sin((hueOff+120)*0.017)*105;
       b = 150 + Math.sin((hueOff+240)*0.017)*105;
    } else if (isPearl) {
       const f = 1.0 - dotH;
       r += f*60; g += (1-f)*40; b += f*80;
    }

    let cr = Math.min(255, (mat.amb * r) + (dotL * mat.diff * r) + (specular * 255));
    let cg = Math.min(255, (mat.amb * g) + (dotL * mat.diff * g) + (specular * 255));
    let cb = Math.min(255, (mat.amb * b) + (dotL * mat.diff * b) + (specular * 255));

    const luma = (cr * 0.299 + cg * 0.587 + cb * 0.114);
    let bucketIdx = Math.floor((luma / 255) * 15) || 0;
    if (bucketIdx < 0) bucketIdx = 0;
    if (bucketIdx > 15) bucketIdx = 15;

    const bRef = buckets[bucketIdx];
    bRef.r += cr; bRef.g += cg; bRef.b += cb;
    bRef.x[bRef.count] = hxPos;
    bRef.y[bRef.count] = hyPos;
    bRef.count++;
  }

  p.background(15);
  const ctx = p.drawingContext;
  const drawW = SQRT3 * radius * 0.45;
  const drawH = radius * 0.9;

  for (let bIdx = 0; bIdx < 16; bIdx++) {
    const bucket = buckets[bIdx];
    if (bucket.count === 0) continue;

    const avgR = bucket.r / bucket.count;
    const avgG = bucket.g / bucket.count;
    const avgB = bucket.b / bucket.count;

    ctx.fillStyle = `rgb(${Math.round(avgR)},${Math.round(avgG)},${Math.round(avgB)})`;
    ctx.beginPath();

    for(let i = 0; i < bucket.count; i++) {
      const cx = bucket.x[i], cy = bucket.y[i];
      ctx.moveTo(cx, cy - drawH);
      ctx.lineTo(cx + drawW, cy - drawH/2);
      ctx.lineTo(cx + drawW, cy + drawH/2);
      ctx.lineTo(cx, cy + drawH);
      ctx.lineTo(cx - drawW, cy + drawH/2);
      ctx.lineTo(cx - drawW, cy - drawH/2);
    }
    ctx.fill();
  }
};
